-- Stable H3 forecast zones. Existing reports and historical predictions are retained.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '120s';
SET LOCAL search_path = public, extensions, pg_catalog;

CREATE TABLE public.spatial_zones (
  id varchar(64) PRIMARY KEY,
  zone_name varchar(100) NOT NULL,
  zone_type varchar(20) NOT NULL DEFAULT 'h3' CHECK (zone_type IN ('h3', 'barangay')),
  boundary_geojson jsonb NOT NULL,
  centroid_lat double precision NOT NULL CHECK (centroid_lat BETWEEN -90 AND 90),
  centroid_lng double precision NOT NULL CHECK (centroid_lng BETWEEN -180 AND 180),
  boundary extensions.geometry(Geometry, 4326) GENERATED ALWAYS AS (
    extensions.ST_SetSRID(extensions.ST_GeomFromGeoJSON(boundary_geojson), 4326)
  ) STORED,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT spatial_zones_valid_boundary CHECK (
    boundary IS NOT NULL AND NOT extensions.ST_IsEmpty(boundary)
    AND extensions.ST_IsValid(boundary)
    AND extensions.GeometryType(boundary) IN ('POLYGON', 'MULTIPOLYGON')
  )
);
CREATE INDEX spatial_zones_boundary_gist ON public.spatial_zones USING gist (boundary);
ALTER TABLE public.spatial_zones ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.spatial_zones FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.spatial_zones TO service_role;

