AS z(id varchar(64), zone_name varchar(100), zone_type varchar(20), boundary_geojson jsonb, centroid_lat double precision, centroid_lng double precision);

-- A live view deliberately avoids a refresh job and stale validation/status changes.
-- ST_Covers includes shared edges; lowest stable zone id assigns each report once.
CREATE VIEW public.zone_weekly_report_history WITH (security_invoker = true) AS
SELECT zone.id AS zone_id,
       date_trunc('week', r.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS week_start,
       count(*)::integer AS report_count,
       coalesce(avg(r.severity_score), 0)::numeric AS avg_severity
FROM public.reports r
CROSS JOIN LATERAL (
  SELECT z.id FROM public.spatial_zones z
  WHERE extensions.ST_Covers(z.boundary, r.location::extensions.geometry)
  ORDER BY z.id LIMIT 1
) zone
WHERE r.validation_status = 'approved'
  AND r.status IS DISTINCT FROM 'rejected'::public.report_status
  AND NOT coalesce(r.flagged_severe, false)
  AND r.created_at IS NOT NULL
  AND r.created_at <= now()
GROUP BY zone.id, date_trunc('week', r.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
REVOKE ALL ON public.zone_weekly_report_history FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.zone_weekly_report_history TO service_role;
COMMENT ON VIEW public.zone_weekly_report_history IS
  'UTC Monday weekly incident arrivals, approved and not rejected/flagged; includes resolved/closed history. Missing zone/week rows mean zero incidents. Service-only live aggregate.';

ALTER TABLE public.hotspot_predictions
  ADD COLUMN zone_id varchar(64) REFERENCES public.spatial_zones(id) ON DELETE RESTRICT,
  ADD COLUMN zone_name varchar(100),
  ADD COLUMN horizon_days integer NOT NULL DEFAULT 30,
  ADD COLUMN forecast_date_start timestamptz,
  ADD COLUMN forecast_date_end timestamptz,
  ADD COLUMN predicted_count numeric(12,2) NOT NULL DEFAULT 0,
  ADD COLUMN predicted_lower_bound numeric(12,2) NOT NULL DEFAULT 0,
  ADD COLUMN predicted_upper_bound numeric(12,2) NOT NULL DEFAULT 0,
  ADD COLUMN growth_velocity_percent numeric(12,2) NOT NULL DEFAULT 0,
  ADD COLUMN historical_points jsonb NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN forecast_points jsonb NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN model_version text,
  ADD CONSTRAINT hotspot_predictions_forward_horizon CHECK (horizon_days IN (7, 30, 90)),
  ADD CONSTRAINT hotspot_predictions_forward_counts CHECK (
    predicted_count >= 0 AND predicted_lower_bound >= 0
    AND predicted_lower_bound <= predicted_count AND predicted_count <= predicted_upper_bound
  ),
  ADD CONSTRAINT hotspot_predictions_forward_dates CHECK (
    zone_id IS NULL OR (forecast_date_start IS NOT NULL AND forecast_date_end IS NOT NULL
      AND forecast_date_end - forecast_date_start = make_interval(days => horizon_days))
  ),
  ADD CONSTRAINT hotspot_predictions_series_arrays CHECK (
    jsonb_typeof(historical_points) = 'array' AND jsonb_typeof(forecast_points) = 'array'
  );
-- NULL zone_id keeps all legacy rows compatible; the old region/date/horizon index stays.
CREATE UNIQUE INDEX hotspot_predictions_zone_horizon_date
  ON public.hotspot_predictions (zone_id, horizon_days, prediction_date);
ALTER TABLE public.hotspot_predictions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.hotspot_predictions FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.hotspot_predictions TO service_role;
COMMENT ON COLUMN public.hotspot_predictions.model_version IS
  'NULL identifies legacy historical clustering rows; zone-timeseries-v1 identifies forward forecasts.';
COMMENT ON TABLE public.spatial_zones IS
  'Stable H3 resolution-8 study grid. Cells intersect envelope lng 121.052..121.115, lat 14.530..14.625; includes adjacent areas and is not a Pasig administrative boundary.';
COMMIT;
